definition.script:
pipeline {
    agent any

    options {
        timestamps()
        disableConcurrentBuilds()
        timeout(time: 20, unit: 'MINUTES')
    }

    environment {
        PROJECT_DIR = 'D:\\VVSS lab 5\\parabank'
        PARABANK_URL = 'http://localhost:8080/parabank/index.htm'
        MAVEN_OPTS = '-Djavax.net.ssl.trustStoreType=WINDOWS-ROOT'
        CARGO_GOAL = 'org.codehaus.cargo:cargo-maven3-plugin:1.10.27'
        SERENITY_GOAL = 'net.serenity-bdd.maven.plugins:serenity-maven-plugin:3.9.0'
    }

    stages {
        stage('Environment') {
            steps {
                bat 'java -version'
                bat 'mvn -version'
            }
        }

        stage('Build ParaBank') {
            steps {
                dir(env.PROJECT_DIR) {
                    bat 'mvn -DskipTests clean package'
                }
            }
        }

        stage('Start ParaBank') {
            steps {
                dir(env.PROJECT_DIR) {
                    bat '''
                        @echo off
                        set JENKINS_NODE_COOKIE=dontKillMe
                        set BUILD_ID=dontKillMe
                        if exist target\\parabank-cargo.log del /q target\\parabank-cargo.log
                        start "parabank" /B cmd /c mvn -DskipTests "%CARGO_GOAL%:run" ^> target\\parabank-cargo.log 2^>^&1
                    '''
                }
            }
        }

        stage('Wait For ParaBank') {
            steps {
                dir(env.PROJECT_DIR) {
                    bat '''
                        @echo off
                        for /L %%i in (1,1,40) do (
                            curl.exe --fail --silent "%PARABANK_URL%" | findstr /C:"name=\\"username\\"" > nul
                            if not errorlevel 1 exit /b 0
                            echo ParaBank not ready yet, attempt %%i
                            ping 127.0.0.1 -n 4 > nul
                        )

                        type target\\parabank-cargo.log
                        exit /b 1
                    '''
                }
            }
        }

        stage('Run Tests') {
            steps {
                dir(env.PROJECT_DIR) {
                    bat 'mvn test "-Dtest=LoginBlackBoxTest,ScenarioBasedTest"'
                    bat 'mvn "%SERENITY_GOAL%:aggregate"'
                }
            }
        }
    }

    post {
        always {
            dir(env.PROJECT_DIR) {
                bat returnStatus: true, script: 'mvn "%CARGO_GOAL%:stop"'
            }

            powershell '''
                $ports = @(8080, 8205, 9001)
                foreach ($port in $ports) {
                    Get-NetTCPConnection -LocalPort $port -ErrorAction SilentlyContinue |
                        Select-Object -ExpandProperty OwningProcess -Unique |
                        ForEach-Object {
                            Stop-Process -Id $_ -Force -ErrorAction SilentlyContinue
                        }
                }
            '''

            dir(env.PROJECT_DIR) {
                junit allowEmptyResults: true, testResults: 'target/surefire-reports/*.xml,target/failsafe-reports/*.xml'
                archiveArtifacts allowEmptyArchive: true, artifacts: 'target/site/serenity/**,target/surefire-reports/**,target/failsafe-reports/**'
            }
        }
    }
}
